#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string input;
    getline(cin, input); // consume the remaining newline after n
    getline(cin, input);

    regex pattern("\\([\\w_]*\\)");
    sregex_token_iterator iter(input.begin(), input.end(), pattern, -1);
    sregex_token_iterator end;

    int maxLength = 0;
    for (; iter != end; ++iter) {
        string part = *iter;
        int length = 0;
        stringstream ss(part);
        string token;
        while (getline(ss, token, '_')) {
            if (!token.empty()) {
                length = max(length, (int)token.length());
            }
        }
        maxLength = max(maxLength, length);
    }

    long long countInside = 0;
    auto words_begin = sregex_iterator(input.begin(), input.end(), pattern);
    auto words_end = sregex_iterator();

    for (auto it = words_begin; it != words_end; ++it) {
        smatch match = *it;
        string inside = match.str().substr(1, match.str().size() - 2);
        stringstream ss(inside);
        string token;
        while (getline(ss, token, '_')) {
            if (!token.empty()) {
                countInside++;
            }
        }
    }

    cout << maxLength << " " << countInside << "\n";

    return 0;
}
